48	const sumBy = <T>(items: T[], amountOf: (item: T) => number): number =>
49	  items.reduce((total, item) => total + amountOf(item), 0);
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	} as const satisfies Record<string, number>;
62	
63	// Internal to the price list, not part of the module's contract. Callers pass
64	// item types as plain strings and learn insurability from basePremiumForType's
65	// refusal; narrowing to this union would imply a compile-time check the module
66	// does not offer and would duplicate the price list at the boundary.
67	type InsurableItemType = keyof typeof BASE_PREMIUMS;
68	
69	// The MHPCO's price list is the authority on what it will insure: a type it
70	// does not list cannot be quoted at all.
71	const basePremiumForType = (type: string): number => {
72	  const basePremium = BASE_PREMIUMS[type as InsurableItemType];
73	  if (basePremium === undefined) {
74	    throw new Error(`the MHPCO does not insure a ${type}`);
75	  }
76	  return basePremium;
77	};
78	
79	const BLOCK_SIZE = 3;
80	const BLOCK_PREMIUM = 60;
81	
82	// Items of one type, quoted together. A group of exactly 3 forms a building
83	// block and is offered at a flat base premium; any other size is priced per
84	// item. "Alike" means the same item type — 2 runes + 1 moonstone is two
85	// groups, so neither is a block.
86	type AlikeGroup = [type: string, items: Item[]];
87	
88	const intoAlikeGroups = (items: Item[]): AlikeGroup[] => {
89	  const groups = new Map<string, Item[]>();
90	  for (const item of items) {
91	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
92	  }
93	  return [...groups];
94	};
95	
96	const isBuildingBlock = ([, items]: AlikeGroup): boolean =>
97	  items.length === BLOCK_SIZE;
98	
99	const basePremiumForGroup = (group: AlikeGroup): number => {
100	  const [type, items] = group;
101	  return isBuildingBlock(group)
102	    ? BLOCK_PREMIUM
103	    : items.length * basePremiumForType(type);
104	};
105	
106	const sumBasePremiums = (items: Item[]): number =>
107	  sumBy(intoAlikeGroups(items), basePremiumForGroup);
108	
109	const CURSE_SURCHARGE_RATE = 0.5;
110	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
111	const HIGH_ENCHANTMENT_THRESHOLD = 5;
112	
113	const isHighlyEnchanted = (item: Item): boolean =>
114	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
115	
116	// Item-specific modifiers apply to the base premium of the affected item, not
117	// to the policy total.
118	const surchargeRateForItem = (item: Item): number =>
119	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
120	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
121	
122	// Surcharges are charged against the item's own base premium, ignoring any
123	// building-block discount the item may be part of.
124	const surchargeForItem = (item: Item): number =>
125	  basePremiumForType(item.type) * surchargeRateForItem(item);
126	
127	const sumItemSurcharges = (items: Item[]): number =>
128	  sumBy(items, surchargeForItem);
129	
130	// Every amount is rounded in the MHPCO's favour, which cuts in opposite
131	// directions on either side of the ledger: a premium owed to the office rounds
132	// up, a payout owed by it rounds down. Only the final figure is rounded;
133	// intermediate amounts stay fractional.
134	const roundPremiumInMHPCOsFavour = Math.ceil;
135	const roundPayoutInMHPCOsFavour = Math.floor;
136	
137	const LOYALTY_DISCOUNT_RATE = 0.2;
138	const LOYALTY_YEARS_THRESHOLD = 2;
139	
140	const isLoyal = (customer: Customer): boolean =>
141	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
142	
143	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
144	
145	// Policy-wide modifiers are summed into one net rate, not compounded. The net
146	// is signed: a loyal customer's discount can outweigh the surcharge.
147	//
148	// The first insurance surcharge applies to every quote — each item in a quote
149	// is treated as a first insurance, regardless of customer history — so it is
150	// not cancelled by the follow-up contract discount.
151	const policyModifierRateFor = (
152	  customer: Customer,
153	  precedingContracts: number,
154	): number =>
155	  FIRST_INSURANCE_SURCHARGE_RATE -
156	  (isLoyal(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
157	  (precedingContracts > 0 ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
158	
159	// Charged against the policy base premium — the sum of all item base premiums —
160	// and added to it, mirroring how surchargeForItem works per item.
161	const policyModifierFor = (
162	  basePremium: number,
163	  customer: Customer,
164	  precedingContracts: number,
165	): number => basePremium * policyModifierRateFor(customer, precedingContracts);
166	
167	const quotePremium = (
168	  items: Item[],
169	  customer: Customer,
170	  precedingContracts: number,
171	): number => {
172	  const basePremium = sumBasePremiums(items);
173	  const itemSurcharges = sumItemSurcharges(items);
174	  const policyModifier = policyModifierFor(
175	    basePremium,
176	    customer,
177	    precedingContracts,
178	  );
179	  return roundPremiumInMHPCOsFavour(
180	    basePremium + itemSurcharges + policyModifier + PROCESSING_FEE,
181	  );
182	};
183	
184	// An item's insured worth, distinct from what it costs to insure.
185	const INSURANCE_VALUES = {
186	  sword: 1000,
187	  amulet: 600,
188	  staff: 800,
189	  potion: 400,
190	  rune: 250,
191	  moonstone: 250,
192	} as const satisfies Record<InsurableItemType, number>;
193	
194	// Keyed off the price list rather than being an independent authority: the
195	// price list decides what is insurable, this table only says what an insurable
196	// item is worth. Reaching it with an uninsurable type means a quote was priced
197	// without being validated, which is a bug in the caller, not bad input — hence
198	// the distinct message.
199	const insuranceValueForType = (type: string): number => {
200	  const insuranceValue = INSURANCE_VALUES[type as InsurableItemType];
201	  if (insuranceValue === undefined) {
202	    throw new Error(`the MHPCO holds no insurance value for a ${type}`);
203	  }
204	  return insuranceValue;
205	};
206	
207	const DEDUCTIBLE = 100;
208	const CAP_MULTIPLE = 2;
209	
210	// A quote step creates a policy; later claim steps refer to it by that step's
211	// index. The cap is consumed as claims are paid.
212	interface Policy {
213	  items: Item[];
214	  remainingCap: number;
215	}
216	
217	// The policy's total insured worth.
218	const insuranceSumFor = (items: Item[]): number =>
219	  sumBy(items, (item) => insuranceValueForType(item.type));
220	
221	// The most the policy will ever pay out, derived from the plain item values.
222	// Nothing that moves the premium moves the cap: item surcharges cannot inflate
223	// it, and the building-block discount cannot deflate it.
224	const capFor = (items: Item[]): number =>
225	  CAP_MULTIPLE * insuranceSumFor(items);
226	
227	// The policy owns its item list: it is copied out of the step so that draining
228	// a claim's pool can never reach back into the caller's scenario.
229	const openPolicy = (items: Item[]): Policy => ({
230	  items: [...items],
231	  remainingCap: capFor(items),
232	});
233	
234	// Claims use their own, higher enchantment threshold — unrelated to the
235	// premium-side high-enchantment surcharge.
236	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
237	const HEAVY_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
238	const FULL_REIMBURSEMENT_RATE = 1;
239	
240	const isHeavilyEnchanted = (item: Item): boolean =>
241	  (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
242	
243	// Damage to a heavily enchanted item is only half reimbursed.
244	//
245	// The spec's dragon-material clause is deliberately absent, not forgotten: it
246	// grants full reimbursement, which is already the default, and the heavy
247	// enchantment rule overrides it where both apply. No input exists for which
248	// reading `material` would change the payout, so a branch on it would be dead
249	// code. Reinstate one only if a rule makes dragon material differ from the
250	// default.
251	const reimbursementRateFor = (item: Item): number =>
252	  isHeavilyEnchanted(item)
253	    ? HEAVY_ENCHANTMENT_REIMBURSEMENT_RATE
254	    : FULL_REIMBURSEMENT_RATE;
255	
256	// Each damage entry is charged against one insured item, which no later entry
257	// may reuse — two sword damages need two insured swords. `unclaimed` is drained
258	// as entries are matched.
259	//
260	// This guard is also what rejects a damage entry naming a type the MHPCO does
261	// not insure at all. Such a type can never have reached a policy —
262	// basePremiumForType refuses it at quote time — so "not insured anywhere" is a
263	// strict subset of "not in this policy", and a separate unknown-type check here
264	// would be unreachable.
265	const claimInsuredItem = (unclaimed: Item[], damage: Damage): Item => {
266	  const at = unclaimed.findIndex((item) => item.type === damage.itemType);
267	  if (at === -1) {
268	    throw new Error(
269	      `the policy does not cover a ${damage.itemType} for this damage`,
270	    );
271	  }
272	  return unclaimed.splice(at, 1)[0];
273	};
274	
275	// A damage report describes harm done, so a negative amount is not a small
276	// claim but a malformed one.
277	const damageAmountOf = (damage: Damage): number => {
278	  if (damage.amount < 0) {
279	    throw new Error(
280	      `a ${damage.itemType} cannot be damaged by ${damage.amount} G`,
281	    );
282	  }
283	  return damage.amount;
284	};
285	
286	// The reimbursement rate applies to the damage first; the deductible comes off
287	// what remains, once per damage event rather than once per claim.
288	const payoutForDamage = (item: Item, damage: Damage): number =>
289	  damageAmountOf(damage) * reimbursementRateFor(item) - DEDUCTIBLE;
290	
291	// Settling a claim consumes the policy's cap, so the policy carries less cover
292	// into the next claim. Kept separate from settleClaim so the state change is
293	// visible where the policy is held rather than hidden behind a pure-looking call.
294	const consumeCap = (policy: Policy, result: ClaimResult): Policy => ({
295	  ...policy,
296	  remainingCap: result.remainingCap,
297	});
298	
299	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
300	  const unclaimed = [...policy.items];
301	  // Per-damage amounts stay fractional; the claim total is rounded once, before
302	  // the cap is applied — rounding a capped figure would round the cap itself.
303	  const roundedClaimTotal = roundPayoutInMHPCOsFavour(
304	    sumBy(damages, (damage) =>
305	      payoutForDamage(claimInsuredItem(unclaimed, damage), damage),
306	    ),
307	  );
308	  // The cap limits what the policy will pay, so a claim beyond it is paid out
309	  // only as far as the cap reaches.
310	  const payout = Math.min(roundedClaimTotal, policy.remainingCap);
311	  return { payout, remainingCap: policy.remainingCap - payout };
312	};
313	
314	// A claim names the quote step that opened its policy. An index matching no
315	// such step is a claim against cover that was never taken out.
316	const policyClaimedAgainst = (
317	  policies: Map<number, Policy>,
318	  policyIndex: number,
319	): Policy => {
320	  const policy = policies.get(policyIndex);
321	  if (policy === undefined) {
322	    throw new Error(`step ${policyIndex} did not open a policy to claim against`);
323	  }
324	  return policy;
325	};
326	
327	const runStep = (
328	  step: Step,
329	  customer: Customer,
330	  precedingContracts: number,
331	  policies: Map<number, Policy>,
332	  stepIndex: number,
333	): QuoteResult | ClaimResult => {
334	  switch (step.op) {
335	    case "quote": {
336	      // Priced before the policy is opened, so an uninsurable type is refused
337	      // by the price list — the authority on insurability — rather than by
338	      // insuranceValueForType, whose refusal reports a caller bug. The two are
339	      // otherwise independent: neither reads the other's effects.
340	      const premium = quotePremium(step.items, customer, precedingContracts);
341	      policies.set(stepIndex, openPolicy(step.items));
342	      return { premium };
343	    }
344	    case "claim": {
345	      const policy = policyClaimedAgainst(policies, step.policy);
346	      const result = settleClaim(policy, step.incident.damages);
347	      policies.set(step.policy, consumeCap(policy, result));
348	      return result;
349	    }
350	  }
351	};
352	
353	// Each quote in a scenario forms a contract, so every quote after the first is
354	// a follow-up. Steps are run in order and a step sees only the contracts that
355	// precede it. Only quote steps create contracts.
356	export const runScenario = (scenario: Scenario): ScenarioResults => {
357	  const results: (QuoteResult | ClaimResult)[] = [];
358	  const policies = new Map<number, Policy>();
359	  let contractsSoFar = 0;
360	  scenario.steps.forEach((step, stepIndex) => {
361	    results.push(
362	      runStep(step, scenario.customer, contractsSoFar, policies, stepIndex),
363	    );
364	    if (step.op === "quote") contractsSoFar += 1;
365	  });
366	  return { results };
367	};
